/** docs/fidelity-unassessed.md: every unassessed Mermaid Fidelity callback of the published
 * result, grouped by who can close it (mermaid-fidelity/unassessed.ts). Generated by
 * `results:snapshot` from the result file alone, so it carries no date but the collection's. */
import { fidelityScoring } from './mermaid-fidelity/scoring.ts'
import { UNASSESSED_OWNER_LABELS, UNASSESSED_OWNERS, unassessedTotals, type UnassessedBreakdown, type UnassessedOwner } from './mermaid-fidelity/unassessed.ts'

/** Where results:snapshot writes the page, relative to the repository root. */
export const FIDELITY_UNASSESSED_PAGE = 'docs/fidelity-unassessed.md'
/** Reasons listed per owner; the rest are summarised in one line. */
const REASONS_PER_OWNER = 15

const cell = (text: string) => text.replaceAll('|', '\\|').replace(/\s+/g, ' ').trim()
const number = (value: number) => value.toLocaleString('en-GB')
const ownerTitle = (owner: UnassessedOwner) => `${UNASSESSED_OWNER_LABELS[owner].owner}: ${UNASSESSED_OWNER_LABELS[owner].title}`

/** Whether every candidate row of a Fidelity result carries the owner breakdown. */
export function hasUnassessedBreakdown(fidelity: any) {
  const rows = (fidelity?.results ?? []).filter((row: any) => row.project !== 'mermaid-js/mermaid')
  return fidelity?.scoring?.protocol === 'fidelity-scored-population-v3' && rows.length > 0 && rows.every((row: any) => row.unassessed && typeof row.unassessed === 'object')
}

/** The page, or undefined for a result merged before the breakdown was recorded. */
export function renderFidelityUnassessed(fidelity: any, label: (project: string, version: string) => string = (project, version) => `${project} ${version}`, catalog?: any) {
  if (!hasUnassessedBreakdown(fidelity)) return undefined
  const scoring = fidelityScoring(fidelity, catalog)
  const rows = scoring.results.filter((row: any) => row.project !== 'mermaid-js/mermaid').map((row: any) => {
    const breakdown = row.unassessed as UnassessedBreakdown, totals = unassessedTotals(breakdown), expected = scoring.score(row).unassessed
    if (totals.total !== expected) throw Error(`${row.project}'s unassessed breakdown covers ${totals.total} callbacks, not the ${expected} scoring leaves unassessed`)
    return { row, name: cell(label(row.project, row.version)), breakdown, ...totals }
  }).sort((a: any, b: any) => b.total - a.total || a.name.localeCompare(b.name))
  const ownerTotals = Object.fromEntries(UNASSESSED_OWNERS.map(owner => [owner, rows.reduce((sum: number, row: any) => sum + row.owners[owner], 0)])) as Record<UnassessedOwner, number>
  const affected = (owner: UnassessedOwner) => rows.filter((row: any) => row.owners[owner] > 0).length
  const total = rows.reduce((sum: number, row: any) => sum + row.total, 0)
  const collected = String(fidelity.collectedThrough ?? '').slice(0, 10)
  const lines = ['# Unassessed Mermaid Fidelity callbacks', '',
    `Generated by \`bun commands.ts results:snapshot\` from the published Fidelity result${collected ? ` (collected through ${collected})` : ''}. Each of the ${number(rows.length)} ranked candidates is scored on the same ${number(scoring.population)} callbacks. A callback is a known outcome when it passed, failed natively, is a verified refusal (Mermaid recognises the refused source as a diagram) or is a confirmed absence (a recorded review confirmed the capability assessment). Every other scored callback is unassessed: it could still pass or fail, which is why the league table shows a possible rank. Across all candidates ${number(total)} callbacks are unassessed. Each has an owner who can close it:`, '']
  for (const owner of UNASSESSED_OWNERS) lines.push(`- **${ownerTitle(owner)}**: closed by ${UNASSESSED_OWNER_LABELS[owner].closedBy}.`)
  lines.push('', 'An adapter limitation that is neither a file that did not load nor a Trident error counts as binding or view work.', '',
    '| Owner | Unassessed callbacks | Candidates affected |', '|---|---:|---:|',
    ...UNASSESSED_OWNERS.map(owner => `| ${ownerTitle(owner)} | ${number(ownerTotals[owner])} | ${affected(owner)} |`),
    `| **Total** | **${number(total)}** | ${rows.filter((row: any) => row.total > 0).length} |`, '',
    '## By candidate', '',
    `| Project | Unassessed ↓ | ${UNASSESSED_OWNERS.map(ownerTitle).join(' | ')} |`, `|---|---:|${UNASSESSED_OWNERS.map(() => '---:').join('|')}|`,
    ...rows.map((row: any) => `| ${row.name} | ${number(row.total)} | ${UNASSESSED_OWNERS.map(owner => number(row.owners[owner])).join(' | ')} |`), '',
    '## Largest reasons by owner', '',
    `Reasons are normalised as in the result's reason tables: first line, numbers as N, at most 160 characters. Up to ${REASONS_PER_OWNER} reasons per owner, with the candidates each affects and their callbacks.`, '')
  for (const owner of UNASSESSED_OWNERS) {
    lines.push(`### ${ownerTitle(owner)} (${number(ownerTotals[owner])})`, '')
    const reasons = new Map<string, { callbacks: number; candidates: { name: string; callbacks: number }[] }>()
    for (const row of rows) for (const [reason, callbacks] of Object.entries(row.breakdown[owner] ?? {}) as [string, number][]) {
      if (!callbacks) continue
      const entry = reasons.get(reason) ?? { callbacks: 0, candidates: [] }
      entry.callbacks += callbacks
      entry.candidates.push({ name: row.name, callbacks })
      reasons.set(reason, entry)
    }
    if (!reasons.size) { lines.push('None.', ''); continue }
    const ranked = [...reasons].sort((a, b) => b[1].callbacks - a[1].callbacks || a[0].localeCompare(b[0]))
    lines.push('| Reason | Callbacks | Candidates |', '|---|---:|---|',
      ...ranked.slice(0, REASONS_PER_OWNER).map(([reason, entry]) => `| ${cell(reason)} | ${number(entry.callbacks)} | ${entry.candidates.sort((a, b) => b.callbacks - a.callbacks || a.name.localeCompare(b.name)).map(candidate => `${candidate.name} (${number(candidate.callbacks)})`).join(', ')} |`), '')
    const rest = ranked.slice(REASONS_PER_OWNER)
    if (rest.length) lines.push(`${rest.length} more ${rest.length === 1 ? 'reason covers' : 'reasons cover'} ${number(rest.reduce((sum, [, entry]) => sum + entry.callbacks, 0))} callbacks.`, '')
    if (owner === 'trident-collection') lines.push(...uncollectedFiles(rows))
  }
  return lines.join('\n').trimEnd() + '\n'
}

/** The files behind `Candidate test not collected`: each candidate's missingFiles entry for
 * a file whose scored callbacks are all adapter limitations, with its setup reason. */
function uncollectedFiles(rows: any[]) {
  const files: string[] = []
  for (const { row, name, owners } of rows) {
    if (!owners['trident-collection']) continue
    const reasons = new Map<string, string>((row.missingFiles ?? []).map((entry: any) => [entry.path, String(entry.reason ?? '')]))
    for (const file of row.perFile ?? []) {
      if (!reasons.has(file.path) || !file.scored?.unassessed || Object.keys(file.counts ?? {}).some(status => status !== 'trident-blocked')) continue
      files.push(`| ${cell(file.path)} | ${name} | ${number(file.scored.unassessed)} | ${cell(reasons.get(file.path)!.split('\n')[0]!.slice(0, 200)) || '(no reason recorded)'} |`)
    }
  }
  if (!files.length) return []
  return ['Files that did not load, with the setup failure each candidate recorded:', '', '| File | Candidate | Scored callbacks | Setup failure |', '|---|---|---:|---|', ...files.sort(), '']
}
